{"content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  int _currentPage = -1;
  bool _isLoadingMore = false;
  bool _hasMorePages = true;

  // ignore: prefer_final_fields — список пополняется через addAll при подгрузке страниц
  List<CurrencyModel> _allCurrencies = [];
  String _searchQuery = '';

  @override
  void initState() {
    super.initState();
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _initAnimation();
    WidgetsBinding.instance.addPostFrameCallback((_) => _loadInitialData());
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _loadInitialData() {
    final currencyRepository = context.read<CurrencyRepository>();
    _currentPage++;

    currencyRepository.fetchRates(const CurrencyPageRequest()).then((CurrencyPage page) {
      if (!mounted) return;
      setState(() {
        _hasMorePages = page.hasMore;
        _allCurrencies.addAll(page.items);
        _filteredCurrenciesNotifier.value = _applyFilter(_searchQuery);

        if (_currentPage == 0) {
          _fadeController.forward();
        }
      });

      currencyRepository.saveCurrencyList(_allCurrencies);
    }).catchError((Object error) {
      debugPrint('Error loading currencies: $error');
      setState(() => _isLoadingMore = false);
    });
  }

  List<CurrencyModel> _applyFilter(String query) {
    if (query.isEmpty) return _allCurrencies;

    final String lowerQuery = query.toLowerCase();
    return _allCurrencies
        .where((CurrencyModel currency) =>
            currency.name.toLowerCase().contains(lowerQuery) ||
            currency.symbol.toLowerCase().contains(lowerQuery))
        .toList(growable: false);
  }

  void _filterCurrencies(String query) {
    setState(() => _searchQuery = query);
  }

  void _loadMore() {
    if (_isLoadingMore || !_hasMorePages) return;

    setState(() => _isLoadingMore = true);
    final currencyRepository = context.read<CurrencyRepository>();
    _currentPage++;

    currencyRepository.fetchRates(CurrencyPageRequest(page: _currentPage)).then((CurrencyPage page) {
      if (!mounted) return;
      setState(() {
        _hasMorePages = page.hasMore;
        _allCurrencies.addAll(page.items);
        _filteredCurrenciesNotifier.value = _applyFilter(_searchQuery);
        _isLoadingMore = false;
      });

      currencyRepository.saveCurrencyList(_allCurrencies);
    }).catchError((Object error) {
      debugPrint('Error loading more currencies: $error');
      if (!mounted) return;
      setState(() => _isLoadingMore = false);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: ValueListenableBuilder<List<CurrencyModel>>(
        valueListenable: _filteredCurrenciesNotifier,
        builder: (BuildContext context, List<CurrencyModel> data, Widget? child) {
          if (_allCurrencies.isEmpty && _hasMorePages) {
            return const Center(child: CircularProgressIndicator());
          }

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ListView.builder(
                    itemCount: data.length + (_hasMorePages ? 1 : 0),
                    itemBuilder: (BuildContext context, int index) {
                      if (index >= data.length && _hasMorePages) {
                        return const Padding(
                          padding: EdgeInsets.all(20.0),
                          child: Center(child: CircularProgressIndicator()),
                        );
                      }

                      final CurrencyModel currency = data[index];

                      return Padding(
                        key: ValueKey(currency.id),
                        padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                        child: CurrencyCard(model: currency),
                      );
                    },
                    padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  ),
                ),
                if (_hasMorePages && !_isLoadingMore)
                  Padding(
                    padding: const EdgeInsets.all(16.0),
                    child: ElevatedButton(
                      onPressed: _loadMore,
                      child: Text(context.loc.showMore),
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}
